#include <bits/stdc++.h>
int main(int c, char** v) { std::mt19937 r(atoi(v[1])); int t = r() % 3 + 1; printf("%d\n", t); while (t--) { int n = r() % 4 + 1; std::vector<std::string> a(n, std::string(n, '0')), b; for (auto& s : a) for (auto& ch : s) ch = r() % 2 ? '1' : '0'; b = a; if (r() % 2) { for (int i = 0; i < n; i++) if (r() % 2) for (auto& ch : b[i]) ch ^= 1; for (int j = 0; j < n; j++) if (r() % 2) for (int i = 0; i < n; i++) b[i][j] ^= 1; } else for (auto& s : b) for (auto& ch : s) ch = r() % 2 ? '1' : '0'; printf("%d\n", n); for (auto& s : a) puts(s.c_str()); puts(""); for (auto& s : b) puts(s.c_str()); } }
